    H,W=len(g),len(g[0])
    crosses=[]
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r][c-1]==3 and g[r][c+1]==3 and g[r-1][c]==3 and g[r+1][c]==3:
                crosses.append((r,c,g[r][c]))
    centers={(r,c) for r,c,_ in crosses}
    out=[row[:] for row in g]
    # horizontal rays first (reading order)
    for r,c,col in crosses:
        for cc in range(W):
            if out[r][cc]==3 or (r,cc) in centers: continue
