def transform(g):
    H,W=len(g),len(g[0])
    crosses=[]; arms={}  # arms[(r,c)] = index of owning cross
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r][c-1]==3 and g[r][c+1]==3 and g[r-1][c]==3 and g[r+1][c]==3:
                crosses.append((r,c,g[r][c]))
    for i,(r,c,_) in enumerate(crosses):
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            arms[(r+dr,c+dc)]=i
    centers={(r,c) for r,c,_ in crosses}
    out=[row[:] for row in g]
    def blocked(r,c,i):
        return (r,c) in arms and arms[(r,c)]!=i or (r,c) in centers and (r,c)!=(crosses[i][0],crosses[i][1])
    # horizontal rays first (reading order)
    for i,(r,c,col) in enumerate(crosses):
        for cc in range(c-1,-1,-1):
            if g[r][cc]==3 or (r,cc) in centers: break
            out[r][cc]=col
        for cc in range(c+1,W):
            if g[r][cc]==3 or (r,cc) in centers: break
            out[r][cc]=col
    # vertical rays second (vertical wins)
    for i,(r,c,col) in enumerate(crosses):
        for rr in range(r-1,-1,-1):
            if g[rr][c]==3 or (rr,c) in centers: break
            out[rr][c]=col
        for rr in range(r+1,H):
            if g[rr][c]==3 or (rr,c) in centers: break
            out[rr][c]=col
    return out
